class Calculator:
    ADDITION = '+'
    SUBTRACTION = '-'
    MULITPLICATION = '*'
    DIVISION = '/'
    POWER = '^'
    LEFT_PAREN = '('
    RIGHT_PAREN = ')'

    PRECEDENCES = {
        ADDITION: 1,
        SUBTRACTION: 1,
        MULITPLICATION: 2,
        DIVISION: 2,
        POWER: 3
    }

    def __init__(self):
        self.operators = {
            Calculator.ADDITION: lambda x, y: x + y,
            Calculator.SUBTRACTION: lambda x, y: x - y,
            Calculator.MULITPLICATION: lambda x, y: x * y,
            Calculator.DIVISION: lambda x, y: x / y,
            Calculator.POWER: lambda x, y: x ** y
        }

    def calculate(self, expression):
        operand_stack = []
        operator_stack = []
        num_buffer = ''

        for char in expression:
            if self.is_number_char(char):
                num_buffer += char
            else:
                if num_buffer:
                    operand_stack.append(float(num_buffer))
                    num_buffer = ''

                if is_operator(char):
                    self.process_operator(operand_stack, operator_stack, char)
                elif char == Calculator.LEFT_PAREN:
                    operator_stack.append(char)
                elif char == Calculator.RIGHT_PAREN:
                    self.process_right_paren(operand_stack, operator_stack)

        if num_buffer:
            operand_stack.append(float(num_buffer))

        while operator_stack:
            operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)

        return operand_stack[-1] if operand_stack else None

    def is_number_char(self, char):
        return char.isdigit() or char == '.'

    def is_operator(self, char):
        return char in (Calculator.ADDITION, Calculator.SUBTRACTION, Calculator.MULITPLICATION, Calculator.DIVISION, Calculator.POWER)

    def process_operator(self, operand_stack, operator_stack, char):
        while (
                operator_stack and
                operator_stack[-1] != Calculator.LEFT_PAREN and
                self.precedence(operator_stack[-1]) >= self.precedence(char)
        ):
            operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)

        operator_stack.append(char)

    def process_right_paren(self, operand_stack, operator_stack):
        while operator_stack and operator_stack[-1] != Calculator.LEFT_PAREN:
            operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)

        operator_stack.pop()

    def precedence(self, operator):
        return Calculator.PRECEDENCES.get(operator, 0)

    def apply_operator(self, operand_stack, operator_stack):
        operator = operator_stack.pop()
        operand2 = operand_stack.pop()
        operand1 = operand_stack.pop()
        result = self.operators[operator](operand1, operand2)
        operand_stack.append(result)
        return operand_stack, operator_stack
